/**
 * Placeholder Convex document types — regenerated by `npx convex dev`.
 */
import type { DataModelFromSchemaDefinition } from 'convex/server';
import type { default as schema } from '../schema';

export type DataModel = DataModelFromSchemaDefinition<typeof schema>;

type AddressFields = {
  full_name: string;
  phone: string;
  line1: string;
  line2: string;
  city: string;
  region: string;
  postal_code: string;
  country: string;
};

type OrderLine = { productId: number; name: string; quantity: number; unitPrice: number };

export type Doc<TableName extends TableNames> = TableName extends 'users'
  ? UserDoc
  : TableName extends 'addresses'
    ? AddressDoc
    : TableName extends 'shoppingBags'
      ? BagDoc
      : TableName extends 'orders'
        ? OrderDoc
        : never;

export type Id<TableName extends TableNames> = string;

export type TableNames = 'users' | 'addresses' | 'shoppingBags' | 'orders';

interface BaseDoc {
  _id: string;
  _creationTime: number;
}

interface UserDoc extends BaseDoc {
  clerkId: string;
  fullName: string;
  email: string;
  createdAt: number;
}

interface AddressDoc extends BaseDoc, AddressFields {
  clerkId: string;
  createdAt: number;
}

interface BagDoc extends BaseDoc {
  clerkId: string;
  items: Array<{ productId: number; quantity: number }>;
  wishlist: number[];
}

interface OrderDoc extends BaseDoc {
  clerkId: string;
  requestId: string;
  items: OrderLine[];
  shippingAddress: AddressFields;
  subtotal: number;
  shipping: number;
  total: number;
  paymentMethod: string;
  paymentStatus: string;
  status: string;
  gatewayOrderId?: string;
  paidAmountInr?: number;
  paidAt?: number;
  createdAt: number;
}
